/** Deterministic FNV-1a hash → avatar URL. Same name always picks same avatar. */
export function avatarForName(name: string): string {
  const s = (name ?? "").trim().toLowerCase();
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return NEETIQ_AVATARS[h % NEETIQ_AVATARS.length];
}

export function isNeetiqAvatar(url: string | null | undefined): boolean {
  return !!url && (NEETIQ_AVATARS as readonly string[]).includes(url);
}
